// api/routers/promo-router.ts
var promoRouter = createRouter({
  validate: publicQuery.input(external_exports.object({ code: external_exports.string(), orderTotal: external_exports.number() })).query(async ({ input }) => {
    const db2 = getDb();
    const code = input.code.toUpperCase();
    const promo = await db2.select().from(promoCodes).where(eq(promoCodes.code, code)).limit(1);
    if (!promo[0]) {
      return { valid: false, message: "Invalid promo code" };
    }
    const p = promo[0];
    if (!p.isActive) {
      return { valid: false, message: "Promo code is inactive" };
    }
    if (p.usageLimit && (p.usageCount ?? 0) >= p.usageLimit) {
      return { valid: false, message: "Promo code usage limit reached" };
    }
    if (p.validFrom && new Date(p.validFrom) > /* @__PURE__ */ new Date()) {
      return { valid: false, message: "Promo code not yet valid" };
    }
    if (p.validUntil && new Date(p.validUntil) < /* @__PURE__ */ new Date()) {
      return { valid: false, message: "Promo code expired" };
    }
    const minAmount = Number(p.minOrderAmount);
    if (minAmount > 0 && input.orderTotal < minAmount) {
      return { valid: false, message: `Minimum order amount $${minAmount} required` };
    }
    let discount = 0;
    if (p.type === "percentage") {
      discount = input.orderTotal * (Number(p.value) / 100);
    } else {
      discount = Number(p.value);
    }
    if (p.maxDiscount && discount > Number(p.maxDiscount)) {
      discount = Number(p.maxDiscount);
    }
    return {
      valid: true,
      discount: Math.round(discount * 100) / 100,
      promoCodeId: p.id,
      message: `Saved $${discount.toFixed(2)}`
    };
  }),
  list: adminQuery.query(async () => {
    const db2 = getDb();
    return db2.select().from(promoCodes).orderBy(promoCodes.createdAt);
  }),
  create: adminQuery.input(
    external_exports.object({
      code: external_exports.string().min(1),
      type: external_exports.enum(["percentage", "fixed"]),
      value: external_exports.number().positive(),
      minOrderAmount: external_exports.number().optional(),
      maxDiscount: external_exports.number().optional(),
      usageLimit: external_exports.number().int().optional(),
      validFrom: external_exports.string().optional(),
      validUntil: external_exports.string().optional()
    })
  ).mutation(async ({ input }) => {
    const db2 = getDb();
    const result = await db2.insert(promoCodes).values({
      code: input.code.toUpperCase(),
      type: input.type,
      value: input.value,
      minOrderAmount: input.minOrderAmount ?? 0,
      maxDiscount: input.maxDiscount ?? null,
      usageLimit: input.usageLimit ?? null,
      validFrom: input.validFrom ? new Date(input.validFrom) : null,
      validUntil: input.validUntil ? new Date(input.validUntil) : null
    });
    const inserted = await db2.select().from(promoCodes).where(eq(promoCodes.id, Number(result.lastInsertRowid))).limit(1);
    return inserted[0];
  }),
  update: adminQuery.input(
    external_exports.object({
      id: external_exports.number(),
      code: external_exports.string().optional(),
      type: external_exports.enum(["percentage", "fixed"]).optional(),
      value: external_exports.number().optional(),
      minOrderAmount: external_exports.number().optional(),
      maxDiscount: external_exports.number().optional(),
      usageLimit: external_exports.number().int().optional(),
      isActive: external_exports.boolean().optional()
    })
  ).mutation(async ({ input }) => {
    const db2 = getDb();
    const { id, ...data } = input;
    await db2.update(promoCodes).set(data).where(eq(promoCodes.id, id));
    const updated = await db2.select().from(promoCodes).where(eq(promoCodes.id, id)).limit(1);
    return updated[0];
  }),
  delete: adminQuery.input(external_exports.object({ id: external_exports.number() })).mutation(async ({ input }) => {
    const db2 = getDb();
    await db2.delete(promoCodes).where(eq(promoCodes.id, input.id));
    return { success: true };
  })
});

// api/routers/shipping-router.ts
var CAIRNS_POSTCODES = ["4870", "4871", "4872", "4873", "4874", "4875", "4876", "4877", "4878", "4879"];
var shippingRouter = createRouter({
  calculate: publicQuery.input(
    external_exports.object({
      postcode: external_exports.string(),
      country: external_exports.string(),
      weightGrams: external_exports.number().default(500)
    })
  ).query(async ({ input }) => {
    const db2 = getDb();
    const { postcode, country, weightGrams } = input;
    if (country.toUpperCase() === "AU" && CAIRNS_POSTCODES.includes(postcode)) {
      return { cost: 0, name: "Cairns Local Delivery (Free)", free: true };
    }
    const countryCode = country.toUpperCase() === "AU" ? "AU" : null;
    const rates = await db2.select().from(shippingRates).where(
      and(
        eq(shippingRates.isActive, true),
        or(
          countryCode ? eq(shippingRates.countryCode, countryCode) : isNull2(shippingRates.countryCode),
          isNull2(shippingRates.countryCode)
        ),
        or(
          isNull2(shippingRates.minWeight),
          sql`${shippingRates.minWeight} <= ${weightGrams}`
        ),
        or(
          isNull2(shippingRates.maxWeight),
          sql`${shippingRates.maxWeight} >= ${weightGrams}`
        )
      )
    );
    if (rates.length === 0) {
      return { cost: 15, name: "Standard Shipping", free: false };
    }
    const bestRate = rates.reduce((best, rate) => {
      if (Number(rate.rate) < Number(best.rate)) return rate;
      return best;
    });
    return {
      cost: Number(bestRate.rate),
      name: bestRate.name,
      free: false
    };
  }),
  listRates: adminQuery.query(async () => {
    const db2 = getDb();
    return db2.select().from(shippingRates).orderBy(shippingRates.id);
  }),
  upsertRate: adminQuery.input(
    external_exports.object({
      id: external_exports.number().optional(),
      name: external_exports.string(),
      countryCode: external_exports.string().optional(),
      region: external_exports.string().optional(),
      minWeight: external_exports.number().optional(),
      maxWeight: external_exports.number().optional(),
      rate: external_exports.number().positive()
    })
  ).mutation(async ({ input }) => {
    const db2 = getDb();
    const { id, ...data } = input;
    if (id) {
      await db2.update(shippingRates).set(data).where(eq(shippingRates.id, id));
      const updated = await db2.select().from(shippingRates).where(eq(shippingRates.id, id)).limit(1);
      return updated[0];
    } else {
      const result = await db2.insert(shippingRates).values(data);
      const inserted = await db2.select().from(shippingRates).where(eq(shippingRates.id, Number(result.lastInsertRowid))).limit(1);
      return inserted[0];
    }
  }),
  deleteRate: adminQuery.input(external_exports.object({ id: external_exports.number() })).mutation(async ({ input }) => {
    const db2 = getDb();
    await db2.delete(shippingRates).where(eq(shippingRates.id, input.id));
    return { success: true };
  })
});

